const int VERMELHO = 12;
const int AMARELO = 11;
const int VERDE = 10;
const int BOTAO = 2;

enum { ABERTO, ATENCAO, FECHADO };

int estado = ABERTO;
unsigned long inicio = 0;

void luzes(int r, int a, int g) {
  digitalWrite(VERMELHO, r);
  digitalWrite(AMARELO, a);
  digitalWrite(VERDE, g);
}

void mudarPara(int novo) {
  estado = novo;
  inicio = millis();
}

void setup() {
  pinMode(VERMELHO, OUTPUT);
  pinMode(AMARELO, OUTPUT);
  pinMode(VERDE, OUTPUT);
  pinMode(BOTAO, INPUT_PULLUP);
  mudarPara(ABERTO);
}

void loop() {
  unsigned long tempo = millis() - inicio;
  switch (estado) {
    case ABERTO:
      luzes(LOW, LOW, HIGH);
      if (tempo >= 3000 || digitalRead(BOTAO) == LOW) mudarPara(ATENCAO);
      break;
    case ATENCAO:
      luzes(LOW, HIGH, LOW);
      if (tempo >= 1000) mudarPara(FECHADO);
      break;
    case FECHADO:
      luzes(HIGH, LOW, LOW);
      if (tempo >= 3000) mudarPara(ABERTO);
      break;
  }
}

