#include <LiquidCrystal.h>

const int IN1 = 8;
const int IN2 = 7;
const int EN = 5;
const int BOTAO = 2;

LiquidCrystal lcd(12, 11, 10, 9, 4, 3);

bool frente = true;
int botaoAnterior = HIGH;

void setup() {
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(EN, OUTPUT);
  pinMode(BOTAO, INPUT_PULLUP);
  lcd.begin(16, 2);
}

void loop() {
  int botao = digitalRead(BOTAO);
  if (botaoAnterior == HIGH && botao == LOW) {
    frente = !frente;
  }
  botaoAnterior = botao;

  int velocidade = map(analogRead(A0), 0, 1023, 0, 255);

  if (frente) {
    digitalWrite(IN1, HIGH);
    digitalWrite(IN2, LOW);
  } else {
    digitalWrite(IN1, LOW);
    digitalWrite(IN2, HIGH);
  }
  analogWrite(EN, velocidade);

  lcd.setCursor(0, 0);
  lcd.print("Vel: ");
  lcd.print(velocidade);
  lcd.print("   ");
  lcd.setCursor(0, 1);
  if (frente) {
    lcd.print("Frente");
  } else {
    lcd.print("Re    ");
  }
  delay(50);
}

