const int BOTAO = 2;
const int LED = 13;
const unsigned long ESPERA = 50;   // ms que a leitura precisa ficar parada

int ultimaLeitura = HIGH;          // a leitura da volta anterior (com quiques)
int estadoEstavel = HIGH;          // o estado "de verdade", já sem ruído
unsigned long ultimaMudanca = 0;
int apertos = 0;
int ledAceso = LOW;

void setup() {
  pinMode(BOTAO, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int leitura = digitalRead(BOTAO);
  if (leitura != ultimaLeitura) {
    ultimaMudanca = millis();      // mexeu: zera o cronômetro
  }
  if (millis() - ultimaMudanca >= ESPERA && leitura != estadoEstavel) {
    estadoEstavel = leitura;
    if (estadoEstavel == LOW) {    // borda de descida = um aperto de verdade
      apertos++;
      ledAceso = !ledAceso;
      digitalWrite(LED, ledAceso);
      Serial.print("Apertos: ");
      Serial.println(apertos);
    }
  }
  ultimaLeitura = leitura;
}

