const int LED_RAPIDO = 13;
const int LED_LENTO = 12;
const int LED_BOTAO = 11;
const int BOTAO = 2;

unsigned long ultimoRapido = 0;
unsigned long ultimoLento = 0;
int estadoRapido = LOW;
int estadoLento = LOW;

void setup() {
  pinMode(LED_RAPIDO, OUTPUT);
  pinMode(LED_LENTO, OUTPUT);
  pinMode(LED_BOTAO, OUTPUT);
  pinMode(BOTAO, INPUT_PULLUP);
}

void loop() {
  unsigned long agora = millis();

  // tarefa 1: LED rápido, a cada 250 ms
  if (agora - ultimoRapido >= 250) {
    ultimoRapido += 250;
    estadoRapido = !estadoRapido;
    digitalWrite(LED_RAPIDO, estadoRapido);
  }

  // tarefa 2: LED lento, a cada 400 ms
  if (agora - ultimoLento >= 400) {
    ultimoLento += 400;
    estadoLento = !estadoLento;
    digitalWrite(LED_LENTO, estadoLento);
  }

  // tarefa 3: o botão acende o LED de resposta na hora
  if (digitalRead(BOTAO) == LOW) {
    digitalWrite(LED_BOTAO, HIGH);
  } else {
    digitalWrite(LED_BOTAO, LOW);
  }
}

