const int IN1 = 8;
const int IN2 = 7;
const int EN = 5;
const unsigned long RAMPA = 1000;      // ms para acelerar (e para frear)
const unsigned long CRUZEIRO = 2000;   // ms na velocidade máxima

void setup() {
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(EN, OUTPUT);
  digitalWrite(IN1, HIGH);   // sentido: para frente
  digitalWrite(IN2, LOW);
}

void loop() {
  unsigned long t = millis();
  unsigned long fimCruzeiro = RAMPA + CRUZEIRO;
  unsigned long fim = fimCruzeiro + RAMPA;
  int pwm;
  if (t < RAMPA) {
    pwm = t * 255 / RAMPA;                    // acelerando
  } else if (t < fimCruzeiro) {
    pwm = 255;                                // cruzeiro
  } else if (t < fim) {
    pwm = (fim - t) * 255 / RAMPA;            // freando
  } else {
    pwm = 0;                                  // parado
  }
  analogWrite(EN, pwm);
}

