    aplicar(255);
  } else if (strcmp(cmd, "DESLIGA") == 0) {
    aplicar(0);
  } else if (strncmp(cmd, "BRILHO ", 7) == 0) {
    int valor = atoi(cmd + 7);
    if (valor < 0 || valor > 255) {
      Serial.println("ERRO: valor");
    } else {
      aplicar(valor);
    }
  } else if (strcmp(cmd, "STATUS") == 0) {
    Serial.print("BRILHO=");
    Serial.println(brilho);
  } else {
