void setup() {
  pinMode(LAMPADA, OUTPUT);
  int primeira = analogRead(SENSOR);
  for (int i = 0; i < N; i++) {
    leituras[i] = primeira;      // começa com o buffer cheio
  }
  soma = (long)primeira * N;
}

void loop() {
  if (millis() - ultimaLeitura < 10) return;
  ultimaLeitura += 10;

  soma -= leituras[posicao];
  leituras[posicao] = analogRead(SENSOR);
  soma += leituras[posicao];
  posicao = (posicao + 1) % N;
  int media = soma / N;

  if (!acesa && media < LIGA_ABAIXO) {
    acesa = true;
  } else if (acesa && media > DESLIGA_ACIMA) {
    acesa = false;
  }
  digitalWrite(LAMPADA, acesa ? HIGH : LOW);
}

