  if (duracao == 0) return 999;   // nada à frente
  return duracao / 58;
}

void mudarPara(int novo) {
  estado = novo;
  inicio = millis();
  Serial.print("Estado: ");
  switch (novo) {
    case DESARMADO: Serial.println("DESARMADO"); break;
    case ARMANDO:   Serial.println("ARMANDO"); break;
    case ARMADO:    Serial.println("ARMADO"); break;
    case DISPARADO: Serial.println("DISPARADO"); break;
  }
}

// true só no instante em que o botão é apertado (borda HIGH -> LOW)
bool apertou() {
  int agora = digitalRead(BOTAO);
  bool borda = (agora == LOW && botaoAnterior == HIGH);
  botaoAnterior = agora;
  return borda;
}

void setup() {
  pinMode(BOTAO, INPUT_PULLUP);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  mudarPara(DESARMADO);
}

void loop() {
  bool clique = apertou();
  switch (estado) {
    case DESARMADO:
      digitalWrite(LED, LOW);
      noTone(BUZZER);
      if (clique) mudarPara(ARMANDO);
      break;
    case ARMANDO:
      digitalWrite(LED, (millis() / 250) % 2);   // pisca enquanto arma
      if (clique) mudarPara(DESARMADO);
      else if (millis() - inicio >= TEMPO_SAIDA) mudarPara(ARMADO);
      break;
    case ARMADO:
      digitalWrite(LED, HIGH);
      if (clique) mudarPara(DESARMADO);
      else if (distanciaCm() < DISTANCIA_ALARME) mudarPara(DISPARADO);
      break;
    case DISPARADO:
      digitalWrite(LED, HIGH);
      tone(BUZZER, 2000);
      if (clique) {
        noTone(BUZZER);
        mudarPara(DESARMADO);
      }
      break;
  }
  delay(10);
}

