const int IN1 = 8, IN2 = 7, ENA = 5;   // motor esquerdo
const int IN3 = 4, IN4 = 2, ENB = 6;   // motor direito
const int TRIG = 10, ECHO = 11;        // ultrassom na frente

const float ALVO = 20.0;               // cm da parede
const float KP = 12.0;
const float KI = 4.0;
const float KD = 1.0;
const float ZONA_INTEGRAL = 10.0;      // só integra perto do alvo (anti-windup)

float integral = 0;
float erroAnterior = 0;
bool primeira = true;
unsigned long ultimo = 0;

// velocidade de -255 (ré) a 255 (frente)
void motor(int in1, int in2, int en, int vel) {
  vel = constrain(vel, -255, 255);
  if (vel >= 0) {
    digitalWrite(in1, HIGH);
    digitalWrite(in2, LOW);
  } else {
    digitalWrite(in1, LOW);
    digitalWrite(in2, HIGH);
    vel = -vel;
  }
  analogWrite(en, vel);
}

float distanciaCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long duracao = pulseIn(ECHO, HIGH, 30000);
  if (duracao == 0) return 400;   // nada no alcance
  return duracao / 58.0;
}

void setup() {
  pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT); pinMode(ENA, OUTPUT);
  pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT); pinMode(ENB, OUTPUT);
  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT);
}

void loop() {
  unsigned long agora = millis();
  if (agora - ultimo < 20) return;           // controle a 50 Hz
  float dt = (agora - ultimo) / 1000.0;
  ultimo = agora;

  float erro = distanciaCm() - ALVO;         // > 0: longe da parede
  if (primeira) { erroAnterior = erro; primeira = false; }

  if (erro > -ZONA_INTEGRAL && erro < ZONA_INTEGRAL) {
    integral += erro * dt;
  } else {
    integral = 0;
  }
  float derivada = (erro - erroAnterior) / dt;
  erroAnterior = erro;

  float u = KP * erro + KI * integral + KD * derivada;
  int vel = constrain(u, -200, 200);
  motor(IN1, IN2, ENA, vel);
  motor(IN3, IN4, ENB, vel);
}

