const int IN1 = 8, IN2 = 7, ENA = 5;   // motor esquerdo
const int IN3 = 4, IN4 = 2, ENB = 6;   // motor direito

const int VEL = 150;                   // PWM usado nas retas e nos giros
const float LADO = 50.0;               // cm
const float BITOLA = 12.0;             // cm entre as rodas
const unsigned long PAUSA = 300;       // ms parado entre os movimentos

// modelo do motor: zona morta de 25, 40 cm/s com PWM 255
const float V_RODA = (VEL - 25) / 230.0 * 40.0;                     // ≈ 21,7 cm/s
const unsigned long T_RETA = LADO / V_RODA * 1000;                   // ≈ 2300 ms
const unsigned long T_GIRO = (PI / 2) * (BITOLA / 2) / V_RODA * 1000; // ≈ 434 ms

struct Passo {
  int esquerda;
  int direita;
  unsigned long duracao;
};

Passo plano[16];
int nPassos = 0;
int atual = 0;
unsigned long inicio = 0;

// velocidade de -255 (ré) a 255 (frente)
void motor(int in1, int in2, int en, int vel) {
  vel = constrain(vel, -255, 255);
  if (vel >= 0) {
    digitalWrite(in1, HIGH);
    digitalWrite(in2, LOW);
  } else {
    digitalWrite(in1, LOW);
    digitalWrite(in2, HIGH);
    vel = -vel;
  }
  analogWrite(en, vel);
}

void rodas(int esquerda, int direita) {
  motor(IN1, IN2, ENA, esquerda);
  motor(IN3, IN4, ENB, direita);
}

void adicionar(int esquerda, int direita, unsigned long duracao) {
  plano[nPassos].esquerda = esquerda;
  plano[nPassos].direita = direita;
  plano[nPassos].duracao = duracao;
  nPassos++;
}

void setup() {
  pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT); pinMode(ENA, OUTPUT);
  pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT); pinMode(ENB, OUTPUT);
  for (int i = 0; i < 4; i++) {
    adicionar(VEL, VEL, T_RETA);       // reta de 50 cm
    adicionar(0, 0, PAUSA);
    adicionar(-VEL, VEL, T_GIRO);      // 90° para a esquerda, no lugar
    adicionar(0, 0, PAUSA);
  }
  rodas(plano[0].esquerda, plano[0].direita);
  inicio = millis();
}

void loop() {
  if (atual >= nPassos) {              // plano cumprido
    rodas(0, 0);
    return;
  }
  if (millis() - inicio >= plano[atual].duracao) {
    atual++;
    inicio += plano[atual - 1].duracao;
    if (atual < nPassos) rodas(plano[atual].esquerda, plano[atual].direita);
  }
}

