const int IN1 = 8, IN2 = 7, ENA = 5;   // motor esquerdo
const int IN3 = 4, IN4 = 2, ENB = 6;   // motor direito
const int TRIG = 10, ECHO = 11;        // ultrassom
const int SENSOR_ESQ = A0, SENSOR_DIR = A1;

const int BASE = 150;
const float KP = 0.15;
const int LINHA = 500;                 // acima disso o sensor está sobre a linha
const int BRANCO = 200;                // abaixo disso o sensor só vê chão branco

enum { SEGUINDO, GIRA_ESQ, CONTORNA, GIRA_DIR, PROCURA, FIM };
int estado = SEGUINDO;
unsigned long inicio = 0;

// velocidade de -255 (ré) a 255 (frente)
void motor(int in1, int in2, int en, int vel) {
  vel = constrain(vel, -255, 255);
  if (vel >= 0) {
    digitalWrite(in1, HIGH);
    digitalWrite(in2, LOW);
  } else {
    digitalWrite(in1, LOW);
    digitalWrite(in2, HIGH);
    vel = -vel;
  }
  analogWrite(en, vel);
}

void rodas(int esquerda, int direita) {
  motor(IN1, IN2, ENA, esquerda);
  motor(IN3, IN4, ENB, direita);
}

long distanciaCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long duracao = pulseIn(ECHO, HIGH, 30000);
  if (duracao == 0) return 999;
  return duracao / 58;
}

void mudarPara(int novo) {
  estado = novo;
  inicio = millis();
}

void setup() {
  pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT); pinMode(ENA, OUTPUT);
  pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT); pinMode(ENB, OUTPUT);
  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT);
}

void loop() {
  unsigned long t = millis() - inicio;
  int esquerdo = analogRead(SENSOR_ESQ);
  int direito = analogRead(SENSOR_DIR);
  switch (estado) {
    case SEGUINDO:
      if (esquerdo < BRANCO && direito < BRANCO) {
        rodas(0, 0);                     // a linha acabou: missão cumprida
        mudarPara(FIM);
      } else if (distanciaCm() < 15) {
        rodas(0, 0);
        mudarPara(GIRA_ESQ);
      } else {
        int correcao = KP * (esquerdo - direito);
        rodas(BASE - correcao, BASE + correcao);
      }
      break;
    case GIRA_ESQ:                       // vira para a esquerda no lugar
      rodas(-150, 150);
      if (t >= 300) mudarPara(CONTORNA);
      break;
    case CONTORNA:                       // anda em frente, passando ao lado do obstáculo
      rodas(150, 150);
      if (t >= 1800) mudarPara(GIRA_DIR);
      break;
    case GIRA_DIR:                       // vira de volta, apontando para a linha
      rodas(150, -150);
      if (t >= 430) mudarPara(PROCURA);
      break;
    case PROCURA:                        // anda até um sensor achar a linha
      rodas(130, 130);
      if (esquerdo > LINHA || direito > LINHA) mudarPara(SEGUINDO);
      break;
    case FIM:
      rodas(0, 0);
      break;
  }
  delay(5);
}
